import itertools
from math import gcd

def is_good_set(U):
    if len(U) < 3: return False
    for trio in itertools.combinations(U, 3):
        if gcd(trio[0], gcd(trio[1], trio[2])) != 1:
            return False
    for pair in itertools.combinations(U, 2):
        u_i, u_j = pair
        found = False
        for u_k in U:
            if u_k != u_i and u_k != u_j:
                if (u_i * u_j) % u_k == 0:
                    found = True
                    break
        if not found: return False
    return True

# Search for good sets with |U| = 4, elements up to some limit
good_nums_4 = set()
limit = 20
for U in itertools.combinations(range(1, limit), 4):
    if is_good_set(U):
        prod = 1
        for x in U: prod *= x
        good_nums_4.add(prod)

print("Good numbers with |U|=4, elements < 20:", sorted(list(good_nums_4)))
